import {
  aggregate,
  createDirectus,
  readItems,
  rest,
  staticToken
} from "@directus/sdk";

const directus = createDirectus(process.env.DIRECTUS_URL)
  .with(rest())
  .with(staticToken(process.env.DIRECTUS_TOKEN));

const since = new Date(Date.now() - 14 * 24 * 60 * 60 * 1000).toISOString();

const [statusRows, recentNotes] = await Promise.all([
  // Let Directus group and count instead of downloading every note.
  directus.request(
    aggregate("lab_notes", {
      aggregate: { count: "*" },
      groupBy: ["status"]
    })
  ),
  // Only the timestamp is needed for the activity series.
  directus.request(
    readItems("lab_notes", {
      fields: ["date_created"],
      filter: { date_created: { _gte: since } },
      limit: -1
    })
  )
]);

const statusSeries = statusRows
  .map((row) => ({ name: row.status, value: Number(row.count) }))
  .sort((a, b) => b.value - a.value);

const activity = new Map();
for (const note of recentNotes) {
  const day = note.date_created.slice(0, 10);
  activity.set(day, (activity.get(day) ?? 0) + 1);
}

export const chartPayload = {
  labels: [...activity.keys()].sort(),
  series: [
    {
      key: "activity",
      label: "Notes created",
      values: [...activity.entries()]
        .sort(([a], [b]) => a.localeCompare(b))
        .map(([, count]) => count)
    }
  ],
  statusSeries
};
